/**
 * Per-agent Slack credential resolution.
 *
 * Multi-agent serve needs one Slack app (and token pair) per agent. Use
 * `envPrefix: "MY_AGENT"` so the pack reads `MY_AGENT_SLACK_BOT_TOKEN` /
 * `MY_AGENT_SLACK_APP_TOKEN` instead of the shared globals.
 */
/** Normalize an agent directory / display name into an env prefix. */
export function envPrefixFromName(name) {
    return name
        .trim()
        .replace(/[^A-Za-z0-9]+/g, "_")
        .replace(/^_+|_+$/g, "")
        .toUpperCase();
}
/** Env var names for a Slack token pair. */
export function slackEnvKeys(prefix) {
    if (prefix === undefined || prefix.trim() === "") {
        return { bot: "SLACK_BOT_TOKEN", app: "SLACK_APP_TOKEN" };
    }
    const normalized = envPrefixFromName(prefix);
    return {
        bot: `${normalized}_SLACK_BOT_TOKEN`,
        app: `${normalized}_SLACK_APP_TOKEN`,
    };
}
/**
 * Credentials that read `{PREFIX}_SLACK_BOT_TOKEN` / `{PREFIX}_SLACK_APP_TOKEN`
 * (or the unprefixed globals when `prefix` is omitted). Resolvers return `""`
 * when unset so multi-agent serve does not fall through to a shared token.
 */
export function credentialsFromEnv(prefix) {
    const keys = slackEnvKeys(prefix);
    return {
        botToken: () => process.env[keys.bot]?.trim() ?? "",
        appToken: () => process.env[keys.app]?.trim() ?? "",
    };
}
async function readExplicitToken(explicit) {
    if (explicit === undefined) {
        return undefined;
    }
    const value = typeof explicit === "function" ? await explicit() : explicit;
    // API transports (objects) carry no raw token to resolve.
    if (typeof value !== "string") {
        return undefined;
    }
    const trimmed = value.trim();
    return trimmed === "" ? undefined : trimmed;
}
/**
 * Resolve a bot token string without throwing. When `credentials.botToken`
 * is set (string or resolver), only that value is used — no global fallback
 * — so a per-agent prefix cannot accidentally bind every mounted agent to
 * one app. When omitted, falls back to `SLACK_BOT_TOKEN`. API transports
 * resolve to `undefined` (they execute calls without a local token).
 */
export async function tryResolveBotToken(credentials) {
    if (credentials?.botToken !== undefined) {
        return readExplicitToken(credentials.botToken);
    }
    return readExplicitToken(process.env.SLACK_BOT_TOKEN);
}
/**
 * Resolve an app-level token without throwing. Same per-agent rules as
 * {@link tryResolveBotToken}.
 */
export async function tryResolveAppToken(credentials) {
    if (credentials?.appToken !== undefined) {
        return readExplicitToken(credentials.appToken);
    }
    return readExplicitToken(process.env.SLACK_APP_TOKEN);
}
